import com.crowdin.client.core.http.impl.json.JacksonJsonTransformer;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Assert;
import org.junit.Test;

public class JacksonJsonTransformerTest {

    @Test
    public void parseValidJsonToProjectClassTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String validJson = "{ \"name\": \"test_project\", \"id\": 1 }";
        Project project = transformer.parse(validJson, Project.class); 

        Assert.assertNotNull(project);
        Assert.assertEquals("test_project", project.getName());
        Assert.assertEquals((Integer) 1, project.getId());
    }

    @Test(expected = CrowdinApiException.class)
    public void parseInvalidJsonToProjectClassTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String invalidJson = "{ {";
        transformer.parse(invalidJson, Project.class);
    }

    @Test
    public void parseValidJsonToLanguageTranslataionsClassTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String validJson = "{ \"languageId\": \"en\", \"translations\": [\"translation1\", \"translation2\"] }";
        LanguageTranslations translations = transformer.parse(validJson, LanguageTranslations.class);

        Assert.assertNotNull(translations);
        Assert.assertEquals("en", translations.getLanguageId());
        Assert.assertEquals(2, translations.getTranslations().size());
        Assert.assertTrue(translations.getTranslations().contains("translation1"));
        Assert.assertTrue(translations.getTranslations().contains("translation2"));
    }

    @Test
    public void convertProjectObjectToJsonStringTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Project project = new Project();
        project.setName("test_project");
        project.setId(1);

        String jsonData = transformer.convert(project); 

        Assert.assertNotNull(jsonData);
        Assert.assertTrue(jsonData.contains("\"name\":\"test_project\""));
        Assert.assertTrue(jsonData.contains("\"id\":1"));
    }

    @Test
    public void convertLanguageTranslationsObjectToJsonStringTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        LanguageTranslations translations = new LanguageTranslations();
        translations.setLanguageId("en");
        translations.setTranslations(Arrays.asList("translation1", "translation2"));

        String jsonData = transformer.convert(translations); 

        Assert.assertNotNull(jsonData);
        Assert.assertTrue(jsonData.contains("\"languageId\":\"en\""));
        Assert.assertTrue(jsonData.contains("\"translations\":[\"translation1\",\"translation2\"]"));
    }
}
